@SpringBootTest(classes = WebApp.class, webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class RandomPortTest {

    @LocalServerPort
    int port;

    @Autowired
    TestRestTemplate restTemplate;

    @Test
    void test() {
        String response = restTemplate.getForObject("http://localhost:" + port + "/ping", String.class);
        assertThat(response).isEqualTo("pong");
    }
}

@SpringBootTest(classes = NoWebApp.class, webEnvironment = SpringBootTest.WebEnvironment.NONE)
class NoWebTest {

    @Autowired
    ApplicationContext context;

    @Test
    void test() {
        assertThat(context.getEnvironment().getProperty("server.port")).isNull();
    }
}

